insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-ylang-ylang', 'ylang-ylang', 'イランイラン', 'Cananga odorata', 'バンレイシ科', 'ミドル', '濃厚な花、甘い、エキゾチック', '甘く華やかで存在感のある香り。リラックス系や特別感のあるブレンドに少量加えると印象が出ます。', '["夜のリラックス","華やかさを足す","甘いフローラル"]', '["relax","happy"]', '["ベルガモット","オレンジ","サンダルウッド","ゼラニウム"]', '濃厚で頭重感を覚える場合があります。少量から使ってください。', '#e7b8c4');
