insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-cedarwood', 'cedarwood', 'シダーウッド', 'Cedrus atlantica', 'マツ科', 'ベース', 'ウッディ、乾いた木、落ち着き', '穏やかな木の香り。ブレンドに安定感を出し、甘い香りを引き締めます。', '["夜の落ち着き","ウッディ調","香りの土台づくり"]', '["relax","sleep","focus"]', '["オレンジ","ラベンダー","ローズマリー","フランキンセンス"]', '重くなりやすいので、トップノートと合わせて少量から調整してください。', '#b89068');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-sandalwood', 'sandalwood', 'サンダルウッド', 'Santalum album', 'ビャクダン科', 'ベース', 'なめらか、ウッディ、クリーミー', 'なめらかで静かな木の香り。余韻が長く、瞑想的なブレンドや高級感の演出に向きます。', '["深いリラックス","香りの余韻","高級感のあるブレンド"]', '["relax","sleep"]', '["フランキンセンス","イランイラン","ベルガモット","ローズ"]', '希少性が高い精油です。由来や品質表示を確認してください。', '#c0a076');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-patchouli', 'patchouli', 'パチュリ', 'Pogostemon cablin', 'シソ科', 'ベース', '土っぽい、甘い、重厚', '個性的で深い土っぽさのある香り。少量でブレンドに奥行きと持続性を加えます。', '["香りの固定","落ち着いた印象","個性的なブレンド"]', '["relax"]', '["ゼラニウム","ベルガモット","サンダルウッド","クラリセージ"]', '非常に存在感が強いため、1滴未満の感覚で少量から調整してください。', '#9b7b5b');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-grapefruit', 'grapefruit', 'グレープフルーツ', 'Citrus paradisi', 'ミカン科', 'トップ', 'ほろ苦い柑橘、軽快、明るい', '軽やかでほろ苦い柑橘の香り。朝や気分転換のブレンドにフレッシュさを足します。', '["朝の気分転換","軽やかな柑橘","リフレッシュ"]', '["energy","happy","refresh"]', '["ローズマリー","ペパーミント","ジュニパーベリー","ゼラニウム"]', '圧搾グレープフルーツは光毒性に注意が必要です。肌使用時は確認してください。', '#f2bf7a');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-lime', 'lime', 'ライム', 'Citrus aurantifolia', 'ミカン科', 'トップ', '鋭い柑橘、爽快、軽い甘さ', 'キレのある爽快な柑橘。甘い香りを軽くしたい時や、リフレッシュ感を出す時に使いやすい精油です。', '["リフレッシュ","明るい印象づくり","甘さの調整"]', '["energy","happy","refresh"]', '["ペパーミント","ジンジャー","レモングラス","シダーウッド"]', '圧搾ライムは光毒性に注意。蒸留品など製品仕様を確認してください。', '#c9d86f');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-mandarin', 'mandarin', 'マンダリン', 'Citrus reticulata', 'ミカン科', 'トップ', 'やさしい柑橘、甘い、軽い', '甘くやさしい柑橘の香り。強い香りが苦手な人にも使いやすく、夜の柑橘ブレンドにも向きます。', '["穏やかな気分転換","家族向けの空間","やさしい甘さ"]', '["relax","happy"]', '["ラベンダー","カモミール","ネロリ","フランキンセンス"]', '柑橘精油として、肌使用時は製品の光毒性情報を確認してください。', '#f0b66f');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-lemongrass', 'lemongrass', 'レモングラス', 'Cymbopogon citratus', 'イネ科', 'トップ', 'レモン様、草、力強い', 'レモンに似た強い草の香り。空間をすっきりさせたい時に少量使うと印象が変わります。', '["リフレッシュ","空間の切り替え","シャープな印象"]', '["refresh","energy"]', '["ライム","ジンジャー","ペパーミント","シダーウッド"]', '刺激が強めです。肌使用では低濃度にし、敏感肌は注意してください。', '#c6ca72');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-chamomile-roman', 'chamomile-roman', 'ローマンカモミール', 'Chamaemelum nobile', 'キク科', 'ミドル', 'リンゴ様、甘い、穏やか', '甘くやさしいハーブ調。夜のリラックスブレンドに丸みを与えます。', '["就寝前","穏やかな香り","やさしいハーブ調"]', '["relax","sleep"]', '["ラベンダー","マンダリン","クラリセージ","サンダルウッド"]', 'キク科に敏感な方は注意してください。', '#e8d799');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-rose', 'rose', 'ローズ', 'Rosa damascena', 'バラ科', 'ミドル', '華やか、濃厚、上品', '少量で華やかさが出る高級感のある香り。フローラルブレンドの印象を大きく変えます。', '["特別感のある香り","気分を上げたい時","フローラルの主役"]', '["happy","relax"]', '["サンダルウッド","ベルガモット","ゼラニウム","ネロリ"]', '高価で濃厚な香りです。少量から使い、品質表示を確認してください。', '#df9aae');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-neroli', 'neroli', 'ネロリ', 'Citrus aurantium var. amara', 'ミカン科', 'ミドル', '白い花、柑橘、上品', 'ビターオレンジの花から得られる上品な香り。落ち着きと明るさを両立したいブレンドに合います。', '["夜のケア時間","上品なフローラル","気分の切り替え"]', '["relax","happy"]', '["ラベンダー","ベルガモット","サンダルウッド","マンダリン"]', '香りが繊細なので、強い精油と合わせる時は量を控えめにしてください。', '#f2d7bc');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-jasmine', 'jasmine', 'ジャスミン', 'Jasminum grandiflorum', 'モクセイ科', 'ミドル', '濃厚な花、甘い、官能的', '甘く濃厚な白花の香り。ごく少量で華やかさと深みを加えます。', '["気分を上げたい時","特別なブレンド","甘いフローラル"]', '["happy","relax"]', '["ベルガモット","サンダルウッド","ローズ","オレンジ"]', '強く香るため少量から調整してください。妊娠中などは専門家に確認してください。', '#e7c0d2');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-palmarosa', 'palmarosa', 'パルマローザ', 'Cymbopogon martinii', 'イネ科', 'ミドル', 'ローズ調、草、軽い甘さ', 'ローズに似た明るい草花の香り。フローラルを軽くしたい時に使いやすい精油です。', '["バランスの良い香り","軽いフローラル","気分転換"]', '["relax","happy"]', '["ゼラニウム","ラベンダー","ベルガモット","シダーウッド"]', '香りが広がりやすいため、少量から調整してください。', '#d9b4a8');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-juniper-berry', 'juniper-berry', 'ジュニパーベリー', 'Juniperus communis', 'ヒノキ科', 'ミドル', '森林、ドライ、すっきり', 'ドライで透明感のある森林調。リフレッシュやウッディ系ブレンドの橋渡しに使いやすい香りです。', '["リフレッシュ","森林感","ドライな印象"]', '["refresh","focus"]', '["グレープフルーツ","ローズマリー","シダーウッド","ラベンダー"]', '持病や妊娠中など体調に不安がある場合は専門家に確認してください。', '#9aae9d');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-cypress', 'cypress', 'サイプレス', 'Cupressus sempervirens', 'ヒノキ科', 'ミドル', '針葉樹、ドライ、端正', 'すっきりとした針葉樹の香り。甘さを抑えた落ち着いたブレンドに向きます。', '["呼吸を整えたい気分","森林調","端正な印象"]', '["refresh","relax"]', '["ベルガモット","ジュニパーベリー","ラベンダー","フランキンセンス"]', '香りがドライに出やすいため、柑橘や花と合わせると使いやすくなります。', '#8ea28f');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-hinoki', 'hinoki', 'ヒノキ', 'Chamaecyparis obtusa', 'ヒノキ科', 'ベース', '和の木、落ち着き、清潔感', '日本らしい木の香り。深呼吸したくなる空間や、落ち着いた和の印象づくりに合います。', '["落ち着いた空間","深呼吸","和のブレンド"]', '["relax","refresh"]', '["ユーカリ","フランキンセンス","ベルガモット","ラベンダー"]', '木部・枝葉など部位で香りが異なるため、製品ごとの印象を確認してください。', '#b99f78');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-ginger', 'ginger', 'ジンジャー', 'Zingiber officinale', 'ショウガ科', 'ミドル', '温かい、スパイシー、ドライ', '温かみのあるスパイス調。柑橘と合わせると元気な印象のブレンドになります。', '["元気を出したい時","温かい印象","スパイスアクセント"]', '["energy","refresh"]', '["オレンジ","ライム","レモングラス","シダーウッド"]', '刺激を感じる場合があるため、肌使用では低濃度から確認してください。', '#c79a67');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-black-pepper', 'black-pepper', 'ブラックペッパー', 'Piper nigrum', 'コショウ科', 'ミドル', 'スパイシー、温かい、ドライ', 'ピリッとした温かみのある香り。重いウッディや柑橘にアクセントを加えます。', '["元気な印象","温かみ","アクセント"]', '["energy","focus"]', '["グレープフルーツ","ローズマリー","フランキンセンス","ジンジャー"]', '刺激が出る場合があります。少量から使用してください。', '#8a7668');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-basil', 'basil', 'バジル', 'Ocimum basilicum', 'シソ科', 'ミドル', 'ハーバル、甘さ、スパイス感', '甘さのあるハーブ調。集中系ブレンドにやわらかな奥行きを加えます。', '["作業前","ハーバルブレンド","気分転換"]', '["focus","refresh"]', '["レモン","ローズマリー","ラベンダー","ペパーミント"]', '種類により成分が異なります。妊娠中や持病がある場合は専門家に確認してください。', '#8bad75');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-marjoram', 'marjoram', 'マジョラム', 'Origanum majorana', 'シソ科', 'ミドル', '温かいハーブ、やさしい、少しスパイシー', '温かみのある穏やかなハーブ調。夜のリラックスブレンドにやさしさを足します。', '["夜のくつろぎ","温かい印象","ハーバル調"]', '["relax","sleep"]', '["ラベンダー","ベルガモット","シダーウッド","クラリセージ"]', '眠気を感じる場合があるため、車の運転前などは避けてください。', '#b8b47c');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-vetiver', 'vetiver', 'ベチバー', 'Vetiveria zizanoides', 'イネ科', 'ベース', '土、根、重厚、スモーキー', '深く重い根の香り。香りの土台や静かな夜のブレンドにごく少量使います。', '["深い落ち着き","香りの固定","重厚感"]', '["relax","sleep"]', '["ラベンダー","サンダルウッド","ベルガモット","フランキンセンス"]', '非常に重く残るため、少量から調整してください。', '#8b735f');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-myrrh', 'myrrh', 'ミルラ', 'Commiphora myrrha', 'カンラン科', 'ベース', '樹脂、ほろ苦い、静か', 'ほろ苦く静かな樹脂の香り。フランキンセンスと合わせると奥行きのある印象になります。', '["静かな時間","樹脂系ブレンド","余韻づくり"]', '["relax"]', '["フランキンセンス","サンダルウッド","ベルガモット","ラベンダー"]', '粘度が高い場合があります。ディフューザーや器具の仕様に注意してください。', '#a98265');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-clove', 'clove', 'クローブ', 'Syzygium aromaticum', 'フトモモ科', 'ミドル', '甘いスパイス、温かい、強い', '甘く強いスパイス調。冬らしい香りや柑橘ブレンドに少量で温かみを加えます。', '["温かい香り","アクセント","季節感"]', '["energy"]', '["オレンジ","シナモン","ジンジャー","シダーウッド"]', '刺激が強い精油です。肌使用は特に低濃度で、敏感肌は避ける判断も必要です。', '#9b654c');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-cinnamon-leaf', 'cinnamon-leaf', 'シナモンリーフ', 'Cinnamomum zeylanicum', 'クスノキ科', 'ミドル', '甘いスパイス、温かい、濃厚', '甘く温かいスパイスの香り。柑橘やウッディと合わせると季節感が出ます。', '["温かみ","冬のブレンド","少量アクセント"]', '["energy","happy"]', '["オレンジ","クローブ","ジンジャー","フランキンセンス"]', '刺激が強いため、肌使用は慎重に。少量から調整してください。', '#b16f4f');
insert or ignore into essential_oils (id, slug, name, botanical_name, family, scent_note, scent_profile, overview, common_uses, mood_slugs, blends_well_with, safety_note, color) values ('oil-spearmint', 'spearmint', 'スペアミント', 'Mentha spicata', 'シソ科', 'トップ', 'やさしいミント、甘い、軽い', 'ペパーミントよりやわらかいミント調。軽い清涼感を出したい時に使いやすい精油です。', '["軽いリフレッシュ","朝の香り","ミントの調整"]', '["refresh","focus"]', '["レモン","ラベンダー","ローズマリー","グレープフルーツ"]', 'ミント系として刺激に注意し、少量から使ってください。', '#9fd0b6');

